(()=>{'use strict';
const games=[["count-parking-tickets","ちゅうしゃけんを くばろう","数","🚗","くるまの だいすうだけ けんを くばろう"],["shape-rocket-parts","ロケットを くみたてよう","形","🚀","ロケットに あう ぶひんを つけよう"],["color-cargo-sort","いろの にもつを はこぼう","色","🚚","おなじ いろの トラックに にもつを のせよう"],["memory-submarine-lights","せんすいかんの ひかり","記憶","🚤","ひかった まどの ばしょを おぼえよう"],["sound-crossing-count","ふみきりの おと","音","🚆","ふみきりの おとを きいて かずを えらぼう"],["direction-airplane-runway","ひこうきの かっそうろ","方向","✈️","やじるしで ひこうきを かっそうろに すすめよう"],["order-fire-rescue","しょうぼうの じゅんび","順序","🚒","ヘルメット・ホース・しゅっぱつの じゅんばん"],["observation-train-window","でんしゃの まどさがし","観察","🚃","まどの なかから おきゃくさんを みつけよう"],["cause-waterwheel","すいしゃを まわそう","因果関係","🚤","みずの りょうで すいしゃの はやさを かえよう"],["operation-crane-load","クレーンで つもう","乗り物操作","🏗️","クレーンを うごかして にもつを つもう"]];const $=x=>document.getElementById(x),id=new URLSearchParams(location.search).get('id'),mode=Math.max(0,games.findIndex(g=>g[0]===id)),g=games[mode];let round=0,step=0,q,locked=true,rev=0,ctx,lastSpeech='';const pick=a=>a[Math.floor(Math.random()*a.length)],shuffle=a=>a.slice().sort(()=>Math.random()-.5),wait=t=>new Promise(r=>setTimeout(r,t));
function say(t){lastSpeech=t;try{speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(t);u.lang='ja-JP';u.rate=.8;speechSynthesis.speak(u)}catch{}}
function tone(f=440){try{ctx??=new(window.AudioContext||window.webkitAudioContext)();ctx.resume();let o=ctx.createOscillator(),v=ctx.createGain(),t=ctx.currentTime;o.frequency.value=f;o.type='triangle';v.gain.setValueAtTime(.001,t);v.gain.exponentialRampToValueAtTime(.06,t+.03);v.gain.exponentialRampToValueAtTime(.001,t+.23);o.connect(v).connect(ctx.destination);o.start(t);o.stop(t+.24)}catch{}}
async function bells(n,r){for(let i=0;i<n;i++){if(r!==rev)return;tone(680);await wait(420)}}
function show(visual,instruction,options){$('visual').textContent=visual;$('instruction').textContent=instruction;$('feedback').textContent='';$('progress').textContent=(round+1)+' / 3';$('choices').replaceChildren();options.forEach(x=>{let b=document.createElement('button');b.className='choice';b.textContent=x;b.onclick=()=>choose(x);$('choices').append(b)});say(instruction);locked=false}
function startRound(){locked=true;step=0;const n=round+1;switch(mode){
case 0:{let count=n+2;q={answer:'🎫 くばる',count,left:count};show('🚗 '.repeat(count)+'\n🎫 0 / '+count,'くるまに ちゅうしゃけんを いちまいずつ くばろう',['🎫 くばる','🔁 もどす']);break}
case 1:{let shapes=['🔺','🟦','⚪'],shape=shapes[round];q={answer:shape};show('🚀  '+shape+' の ぶひん','ロケットの あいた ところに あう かたちを えらぼう',shuffle(shapes));break}
case 2:{let colors=['🔴','🟡','🔵'],color=colors[round];q={answer:color};show('🚚  '+color+'  📦','この にもつを おなじ いろの トラックに のせよう',shuffle(colors));break}
case 3:{let p=pick([1,2,3,4]);q={answer:String(p),hidden:false};show('🚤  '+[1,2,3,4].map(x=>x===p?'💡':'▫️').join('  '),'ひかった まどを おぼえてね',['👀 おぼえた']);break}
case 4:{let count=n+1;q={answer:String(count),count};show('🚆  🔔','ふみきりの ベルが なんかい なるか きこう',['1','2','3','4','🔊 もういちど']);bells(count,rev);break}
case 5:{let path=[['➡️','⬆️'],['⬆️','➡️','⬇️'],['➡️','➡️','⬆️','➡️']][round];q={path,position:0,answer:path[0]};show('✈️  '+'▫️'.repeat(path.length)+'  🛬','ひこうきを やじるしで かっそうろへ すすめよう',shuffle(['⬅️','➡️','⬆️','⬇️']));break}
case 6:{let path=['⛑️ かぶる','🧯 ホース','🚒 しゅっぱつ'];q={path,position:0,answer:path[0]};show('🚒  ⛑️  🧯','しょうぼうの じゅんびを じゅんばんに しよう',shuffle(path));break}
case 7:{let animals=['🐶','🐱','🐰'],target=animals[round];q={answer:target};show('🚃  '+shuffle([...animals,'🐻','🐼']).join('  '),'でんしゃの まどから '+{'🐶':'いぬ','🐱':'ねこ','🐰':'うさぎ'}[target]+'を さがしてね',shuffle(animals));break}
case 8:{let target=[1,3,2][round];q={answer:['💧 すこし','💦 たくさん','🚰 とめる'][target===1?0:target===3?1:2],target};show('🚤  🌊  ⚙️','すいしゃを '+(target===1?'ゆっくり':target===3?'はやく':'とめて')+' まわそう',['💧 すこし','💦 たくさん','🚰 とめる']);break}
case 9:{let count=n+1;q={answer:'⬆️ あげる',position:0,count,phase:0};show('🏗️  📦'.repeat(count),'クレーンで にもつを もちあげて トラックに のせよう',['⬆️ あげる','➡️ はこぶ','⬇️ おろす']);break}
}}
function wrong(){locked=false;$('feedback').textContent='もういっかい 👆';say('おしいね。 もういっかい やってみよう')}
async function correct(r){tone(750);$('feedback').textContent='できたね！ ⭐';say('せいかい！ できたね！');await wait(700);if(r!==rev)return;round++;round<3?startRound():finish()}
async function choose(x){if(locked)return;locked=true;const r=rev;
if(mode===3&&!q.hidden){q.hidden=true;$('visual').textContent='🚤  ❔ ❔ ❔ ❔';$('instruction').textContent='どの まどが ひかったかな？';$('choices').replaceChildren();['1','2','3','4'].forEach(x=>{let b=document.createElement('button');b.className='choice';b.textContent=x;b.onclick=()=>choose(x);$('choices').append(b)});say($('instruction').textContent);locked=false;return}
if(mode===4&&x==='🔊 もういちど'){bells(q.count,r);locked=false;return}
if(mode===0){if(x==='🔁 もどす'){q.left=q.count;$('visual').textContent='🚗 '.repeat(q.count)+'\n🎫 0 / '+q.count;locked=false;return}q.left--;tone(420);$('visual').textContent='🚗 '.repeat(q.count)+'\n🎫 '+(q.count-q.left)+' / '+q.count;if(q.left>0){locked=false;return}return correct(r)}
if(mode===5||mode===6){if(x!==q.answer)return wrong();q.position++;tone(440);$('visual').textContent=(mode===5?'✈️':'🚒')+'  '+'⭐'.repeat(q.position)+'  🏁';if(q.position<q.path.length){q.answer=q.path[q.position];$('instruction').textContent='つぎは '+q.answer;say($('instruction').textContent);locked=false;return}return correct(r)}
if(mode===9){let sequence=['⬆️ あげる','➡️ はこぶ','⬇️ おろす'];if(x!==sequence[q.phase])return wrong();q.phase++;tone(480);$('visual').textContent='🏗️  '+'⭐'.repeat(q.position)+'  '+sequence[Math.min(q.phase,2)];if(q.phase===3){q.position++;q.phase=0}if(q.position>=q.count)return correct(r);$('instruction').textContent='つぎは '+sequence[q.phase];say($('instruction').textContent);locked=false;return}
if(x!==q.answer)return wrong();
if(mode===8)$('visual').textContent='🚤  ⚙️ '+(x==='🚰 とめる'?'⏹️':x==='💦 たくさん'?'💨💨💨':'💨');
return correct(r)}
function finish(){locked=true;$('progress').textContent='3 / 3';$('visual').textContent='🎉 '+g[3]+' 🎉';$('instruction').textContent='ぜんぶ できたね！';say('ぜんぶ できたね！');$('choices').replaceChildren();[['🔁 もういちど',intro],['🏠 おうちへ',()=>location.href='../../index.html']].forEach(([x,fn])=>{let b=document.createElement('button');b.className='choice';b.textContent=x;b.onclick=fn;$('choices').append(b)})}
function intro(){rev++;try{speechSynthesis.cancel()}catch{}round=0;locked=true;$('progress').textContent='あそびかた';$('visual').textContent=g[3]+'  👆';$('instruction').textContent=g[4];$('feedback').textContent='';$('choices').replaceChildren();let b=document.createElement('button');b.className='choice';b.textContent='▶️ はじめる';b.onclick=()=>{try{ctx??=new(window.AudioContext||window.webkitAudioContext)();ctx.resume()}catch{}startRound()};$('choices').append(b)}
$('title').textContent=g[1];document.title=g[1];$('repeat').onclick=()=>{if(mode===4&&q&&!locked)bells(q.count,rev);else say(lastSpeech||g[4])};$('again').onclick=intro;addEventListener('pagehide',()=>{rev++;try{speechSynthesis.cancel()}catch{}});intro();
})();